import numpy as np
import time
from scipy.optimize import linprog, minimize
import multiprocessing

# --- Stage 1: My Enhanced Generator (from ID 320) ---
def seed_praxis(n=32, seed=0):
    np.random.seed(seed)
    centers = np.array([[(j*0.16)+0.1, (i*0.16)+0.1] for i in range(6) for j in range(6)][:n])
    centers += (np.random.rand(n, 2) - 0.5) * 0.04
    x0 = np.zeros(n*3); x0[0::3]=centers[:,0]; x0[1::3]=centers[:,1]; x0[2::3]=0.05
    return np.clip(x0, 1e-6, 1-1e-6)

def seed_verity_farthest(n=32, seed=0):
    rng = np.random.default_rng(seed)
    points = [rng.uniform(0.1, 0.9, 2)]
    for _ in range(n - 1):
        candidates = rng.uniform(0.1, 0.9, (200, 2))
        dist_sq = np.sum((candidates[:, np.newaxis, :] - np.array(points)[np.newaxis, :, :])**2, axis=-1)
        min_dist_sq = np.min(dist_sq, axis=1)
        points.append(candidates[np.argmax(min_dist_sq)])
    centers = np.array(points)
    x0 = np.zeros(n*3); x0[0::3]=centers[:,0]; x0[1::3]=centers[:,1]; x0[2::3]=0.05
    return np.clip(x0, 1e-6, 1-1e-6)

def seed_triangular_lattice(n=32, seed=0):
    np.random.seed(seed)
    rows = 6; cols = 6; points = []
    for r in range(rows):
        for c in range(cols):
            x = (c + 0.5 * (r % 2)) / cols
            y = r * np.sqrt(3) / 2 / rows
            points.append([x, y])
    centers = np.array(points[:n])
    centers[:, 0] = (centers[:, 0] - centers[:, 0].min()) / (centers[:, 0].max() - centers[:, 0].min()) * 0.9 + 0.05
    centers[:, 1] = (centers[:, 1] - centers[:, 1].min()) / (centers[:, 1].max() - centers[:, 1].min()) * 0.9 + 0.05
    angle = np.random.uniform(0, np.pi/2); rot_matrix = np.array([[np.cos(angle), -np.sin(angle)], [np.sin(angle), np.cos(angle)]])
    centers_mean = np.mean(centers, axis=0)
    centers = (centers - centers_mean) @ rot_matrix.T + centers_mean
    centers = np.clip(centers, 0.05, 0.95)
    x0 = np.zeros(n*3); x0[0::3]=centers[:,0]; x0[1::3]=centers[:,1]; x0[2::3]=0.05
    return np.clip(x0, 1e-6, 1-1e-6)

def objective_slsqp(x): return -np.sum(x[2::3])
def constraints_slsqp(x):
    n=32; C=x.reshape(n,3)[:,:2]; r=x[2::3]
    dist_sq=np.sum((C[:,np.newaxis,:]-C[np.newaxis,:,:])**2, axis=-1)
    I, J = np.triu_indices(n, 1)
    return np.concatenate([dist_sq[I,J]-(r[I]+r[J])**2, C[:,0]-r, 1-C[:,0]-r, C[:,1]-r, 1-C[:,1]-r])

def run_single_slsqp_start(x0):
    n=32; bounds=[(1e-6,1-1e-6),(1e-6,1-1e-6),(1e-6,0.5)]*n; con={'type':'ineq','fun':constraints_slsqp}
    res = minimize(objective_slsqp, x0, method='SLSQP', bounds=bounds, constraints=con, options={'maxiter':175, 'ftol':1e-10})
    if res.success: return -res.fun, res.x
    return -np.inf, x0

# --- Stage 2: Verity I's Refiner (from ID 299) ---
def _pairwise_distances(c): return np.sqrt(np.sum((c[:,None,:]-c[None,:,:])**2, axis=-1))
def _boundary_margins(c): return np.minimum.reduce([c[:,0], 1-c[:,0], c[:,1], 1-c[:,1]])

def _solve_lp_for_radii(centers):
    n=centers.shape[0]; b=_boundary_margins(centers); D=_pairwise_distances(centers)
    rows, rhs = [], []; I,J = np.triu_indices(n,1)
    A_ub=np.zeros((len(I),n)); A_ub[np.arange(len(I)),I]=1.0; A_ub[np.arange(len(I)),J]=1.0
    b_ub=D[I,J]
    c = -np.ones(n); bounds = [(0.0, float(max(0.0, bi))) for bi in b]
    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    return (res.x, -res.fun, True) if res.success else (np.zeros(n), 0.0, False)

def _compute_slacks(c, r):
    n=c.shape[0]; D=_pairwise_distances(c); Rsum=r[:,None]+r[None,:]; p_slacks=D-Rsum; np.fill_diagonal(p_slacks, np.inf)
    b_slacks=np.stack([c[:,0]-r, 1-c[:,0]-r, c[:,1]-r, 1-c[:,1]-r], axis=1)
    return b_slacks, p_slacks, np.minimum(np.min(p_slacks, axis=1), np.min(b_slacks, axis=1))

def _aggregated_direction(i, c, b_slacks, p_slacks):
    thresh=1e-4; g=np.zeros(2); dirs=np.array([[1,0],[-1,0],[0,1],[0,-1]])
    for k in range(4):
        if b_slacks[i,k] <= thresh: g += (1/(b_slacks[i,k]+1e-9)) * dirs[k]
    for j in range(c.shape[0]):
        if i==j: continue
        if p_slacks[i,j] <= thresh:
            dvec = c[i]-c[j]; dij = np.linalg.norm(dvec)
            if dij>0: g += (1/(p_slacks[i,j]+1e-9)) * (dvec/dij)
    nrm = np.linalg.norm(g)
    if nrm < 1e-14:
        D=_pairwise_distances(c); j=np.argmin(np.where(D[i]>0,D[i],np.inf))
        g = (c[i]-c[j])/D[i,j] if np.isfinite(D[i,j]) and D[i,j]>0 else np.array([0.5,0.5])-c[i]
        nrm = np.linalg.norm(g)
    return g / max(nrm, 1e-14)

def _clip_box(c): return np.clip(c, 1e-9, 1.0 - 1e-9)

def construct_packing() -> tuple:
    n = 32
    # --- Stage 1: Generate a candidate with the enhanced parallel SLSQP method ---
    num_starts_s1 = 128
    seeds = []
    for i in range(num_starts_s1):
        seed_type = i % 3
        if seed_type == 0: seeds.append(seed_praxis(seed=i))
        elif seed_type == 1: seeds.append(seed_verity_farthest(seed=i))
        else: seeds.append(seed_triangular_lattice(seed=i))

    best_x_s1, best_f_s1 = None, -np.inf
    with multiprocessing.Pool(processes=multiprocessing.cpu_count()) as pool:
        results = pool.map(run_single_slsqp_start, seeds)
    for fun, x in results:
        if fun > best_f_s1: best_f_s1, best_x_s1 = fun, x
    if best_x_s1 is None: best_x_s1 = seeds[0]

    bounds=[(1e-6,1-1e-6),(1e-6,1-1e-6),(1e-6,0.5)]*n; con={'type':'ineq','fun':constraints_slsqp}
    res_s2 = minimize(objective_slsqp, best_x_s1, method='SLSQP', bounds=bounds, constraints=con, options={'maxiter':2000, 'ftol':1e-12})
    final_x = res_s2.x if res_s2.success and -res_s2.fun > best_f_s1 else best_x_s1

    centers = final_x.reshape(n,3)[:,:2]
    radii, obj, ok = _solve_lp_for_radii(centers)
    if not ok: return centers, np.maximum(final_x[2::3], 1e-9)

    # --- Stage 2: Refine the candidate using Verity I's algorithm ---
    best_centers, best_radii, best_obj = centers.copy(), radii.copy(), obj
    cur_centers, cur_radii, cur_obj = centers.copy(), radii.copy(), obj

    start_time = time.time(); time_budget = 300.0; step_schedule = [5e-4, 2e-4, 1e-4, 5e-5, 2e-5, 1e-5]; improve_tol = 1e-8

    for it in range(400): # More refinement iterations
        if time.time() - start_time > time_budget: break
        b_slacks, p_slacks, min_slack = _compute_slacks(cur_centers, cur_radii)
        i = int(np.argmin(min_slack))
        direction = _aggregated_direction(i, cur_centers, b_slacks, p_slacks)

        accepted = False
        for step in step_schedule:
            trial_centers = cur_centers.copy()
            trial_centers[i] += step * direction
            trial_centers = _clip_box(trial_centers)
            tr_r, tr_obj, ok = _solve_lp_for_radii(trial_centers)
            if ok and tr_obj > cur_obj + improve_tol:
                cur_centers, cur_radii, cur_obj = trial_centers, tr_r, tr_obj
                accepted = True
                if tr_obj > best_obj + improve_tol:
                    best_centers, best_radii, best_obj = cur_centers.copy(), cur_radii.copy(), cur_obj
                break
        if not accepted and it > 100: break

    return best_centers, np.maximum(best_radii * (1.0 - 1e-12), 1e-9)
